    try:
        top_n("not a list", 1)
        assert False, "expected TypeError"
    except TypeError:
        pass


def test_non_int_n_raises_type_error():
    try:
        top_n([1, 2, 3], 1.5)
        assert False, "expected TypeError"
    except TypeError:
        pass

